    author: authorJoel,
    coverImage: "https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?auto=format&fit=crop&w=1200&q=80",
    imageAlt: "Flutter mobile application welcome screen running on Android and iOS devices",
